package com.personalstudyplanner;
import com.personalstudyplanner.model.*;import com.personalstudyplanner.service.*;import java.time.LocalDate;import java.util.*;
public class Main {public static void main(String[] args){System.out.println("=== PERSONALISED STUDY PLANNER ===");List<Topic> topics=new ArrayList<>();Scanner sc=new Scanner(System.in);StudyPlanner planner=new StudyPlanner(new PriorityCalculator());boolean running=true;while(running){System.out.println("\n1. Add Topic\n2. Generate Study Plan\n3. Complete Topic\n4. View Revision Plan\n5. Exit\nChoose: ");String choice=sc.nextLine();try{switch(choice){case "1"->addTopic(sc,topics);case "2"->showPlan(planner,topics,sc);case "3"->completeTopic(sc,topics);case "4"->showRevisions(sc,topics);case "5"->running=false;default->System.out.println("Invalid menu option.");}}catch(IllegalArgumentException e){System.out.println("Input error: "+e.getMessage());}}sc.close();}
private static void addTopic(Scanner s,List<Topic> t){System.out.print("Topic name: ");String name=s.nextLine();System.out.print("Difficulty (1-5): ");int d=Integer.parseInt(s.nextLine());System.out.print("Importance (1-5): ");int i=Integer.parseInt(s.nextLine());System.out.print("Estimated minutes: ");int m=Integer.parseInt(s.nextLine());System.out.print("Deadline (YYYY-MM-DD): ");LocalDate date=LocalDate.parse(s.nextLine());System.out.print("Progress (0-100): ");int p=Integer.parseInt(s.nextLine());t.add(new Topic(t.size()+1,name,d,i,m,date,p));System.out.println("Topic added.");}
private static void showPlan(StudyPlanner p,List<Topic> t,Scanner s){System.out.print("Available minutes today: ");int m=Integer.parseInt(s.nextLine());List<StudySession> plan=p.generate(t,m);if(plan.isEmpty())System.out.println("No study sessions can be planned.");else plan.forEach(x->System.out.println("Topic #"+x.topicId()+" - "+x.durationMinutes()+" minutes"));}
private static void completeTopic(Scanner s,List<Topic> t){System.out.print("Topic id: ");int id=Integer.parseInt(s.nextLine());t.stream().filter(x->x.getId()==id).findFirst().orElseThrow(()->new IllegalArgumentException("Topic not found")).updateProgress(100);System.out.println("Topic completed. Revision sessions can now be generated.");}
private static void showRevisions(Scanner s,List<Topic> t){System.out.print("Completed topic id: ");int id=Integer.parseInt(s.nextLine());Topic topic=t.stream().filter(x->x.getId()==id).findFirst().orElseThrow(()->new IllegalArgumentException("Topic not found"));new RevisionPlanner().plan(topic).forEach(System.out::println);}}
